            vg.w = w; vg.h = h; vg.dpr = dpr;
            ['vg-bg', 'vg-gl', 'vg-fx'].forEach(id => {
                const c = document.getElementById(id);
                c.width = Math.round(w * dpr); c.height = Math.round(h * dpr);
            });
            const bg = document.getElementById('vg-bg').getContext('2d');
            bg.setTransform(dpr, 0, 0, dpr, 0, 0);
            const grd = bg.createRadialGradient(w * 0.5, h * 0.5, 0, w * 0.5, h * 0.5, Math.max(w, h) * 0.75);
            grd.addColorStop(0, '#0d1236'); grd.addColorStop(0.55, '#06061a'); grd.addColorStop(1, '#020208');
